import {liveAdapter} from './live-adapters.js';
import {sceneCodec} from './live-codec.js';
export function bindLiveMode(mode,room,playerId,send){
 const slot=room.players.findIndex(p=>p.id===playerId),host=slot===0,adapter=liveAdapter(mode,room),codec=sceneCodec(mode),physical=mode.input,ui={...mode.ui},tick=mode.tick.bind(mode),finish=mode.finish.bind(mode);
 let latest=room,sequence=room.state.sequence||0,inputAt=0,frameAt=0,finished=false,pending=null,start=performance.now(),lastFrame=0,actionsKey='',charge={},lastInputs=Array(room.players.length).fill(0),waiting=true,disposed=false,resultShown=false,forceFull=true;
 const hud={main:'FRIENDS ARE JOINING',sub:'Loading the shared arena',note:'',actions:[]};mode.ui={...ui,status:(main,sub='')=>{hud.main=String(main).slice(0,200);hud.sub=String(sub).slice(0,200);},note:text=>{hud.note=String(text).slice(0,500);},power:value=>{hud.power=value;ui.power?.(value);},actions:actions=>{hud.actions=actions;mode.baseActions=actions;},end:()=>{},sound:name=>{ui.sound(name);if(name==='step')return;if(host&&latest.state.ready.length===room.players.length)send({type:'sound',name});}};
 mode.roomPlayers=room.players;mode.liveFocus=adapter.people[slot]||adapter.people[0];mode.online=true;mode.roomCode=room.code;mode.liveSeat=slot;mode.update=adapter.update;
 function ownControls(){const list=adapter.controls(slot)||[];const active=room.type!=='turns'||latest.state.seat===slot;const value=list.map(a=>({...a,key:String(a.key||'Space'),id:String(a.id),disabled:!active||!!a.disabled})),key=JSON.stringify(value);if(key!==actionsKey){actionsKey=key;mode.actions=value;ui.actions(value);}return value;}
 function draw(){const scores=latest.state.scores||adapter.scores();ui.status(room.type==='turns'?hud.main:room.players[slot].name+': '+scores[slot]+' · BEST: '+Math.max(...scores),hud.sub);if(waiting)ui.note('Waiting for all '+room.players.length+' human players to load…');else if(!host&&lastFrame&&performance.now()-lastFrame>2500)ui.note('Waiting for the host connection. Keep this tab open to resume.');else if(room.type==='turns')ui.note((latest.state.seat===slot?'YOUR TURN':room.players[latest.state.seat].name+' is playing')+' · Everyone watches the same arena.');else if(hud.note)ui.note(hud.note);ownControls();}
 const controlInput=()=>{const raw=physical.vector(),direction=['penalties','onepole','rubberband','alasa','counters','chaskele'].includes(room.game)?raw:(mode.world.movementVector?.(raw)||raw);return{...(['pampanaa','shooting'].includes(room.game)?{heading:mode.heading}:{}),x:Math.max(-1,Math.min(1,direction.x)),z:Math.max(-1,Math.min(1,direction.z)),sprint:!!physical.sprint};};
 function transmit(extra={}){if(disposed||finished||latest.phase!=='playing')return;const input={...controlInput(),...extra};if(host)acceptInput(slot,input);else send({type:'input',input});}
 function acceptInput(index,input){if(index<0||index>=room.players.length)return;lastInputs[index]=performance.now();mode.liveInputs[index]=input;if(!waiting&&(input.action||input.point))adapter.action(index,input);}
 mode.cancelCharge=()=>{charge={};};mode.hold=id=>{charge[id]=performance.now();};mode.action=id=>{transmit({action:String(id),power:charge[id]===undefined?.4:Math.min(1.2,(performance.now()-charge[id])/1000)});delete charge[id];};
 mode.hit=({point,id})=>{if(!point)return;transmit({point:{x:point.x,y:point.y,z:point.z},...(id?.i!==undefined?{pick:id.i}:{})});};
 mode.finish=(title,detail,success=true)=>{if(finished||pending)return;if(['fourcorners','laski'].includes(room.game)&&mode.active.filter(Boolean).length>1)return;mode.done=true;pending={type:'round-end',seat:latest.state.seat,scores:adapter.scores().map(v=>Math.max(0,Math.round(v||0))),...(mode.liveWinners?{winners:mode.liveWinners}:{})};};
 function camera(){if(['pampanaa','shooting'].includes(room.game)){const p=adapter.people[slot];if(p?.visible){mode.world.followTarget=null;mode.world.desired.set(p.position.x-Math.sin(mode.heading)*2.4,2.2,p.position.z-Math.cos(mode.heading)*2.4);mode.world.targetLook.set(p.position.x+Math.sin(mode.heading)*7,1.5+(mode.pitch||0)*6,p.position.z+Math.cos(mode.heading)*7);mode.world.cameraKind='neighbourhood';}return;}if(['football','fourcorners','laski','sulia','stay','pilolo','pampanaa','shooting','police','sansankroma'].includes(room.game)){const person=adapter.people[slot];if(['fourcorners','laski','sulia','stay'].includes(room.game))return;if(person?.visible){mode.world.follow(person,room.game==='football');if(mode.marker&&room.game==='football')mode.marker.position.set(person.position.x,.03,person.position.z);}}}
 mode.tick=(dt,t)=>{
  if(disposed||finished)return;const now=performance.now();waiting=latest.state.ready.length<room.players.length;
  if(now-inputAt>100){transmit();inputAt=now;}
  if(host){latest.state.scores=adapter.scores();for(let i=0;i<lastInputs.length;i++)if(now-lastInputs[i]>350)mode.liveInputs[i]={x:0,z:0,sprint:false};
   if(!waiting&&!mode.done)tick(dt,t);
   if(pending&&now-start>8200){if(send(pending)!==false){pending=null;finished=true;}return;}
   if(now-frameAt>100&&!waiting){const frame={...codec.capture(forceFull||sequence===0),main:hud.main,sub:hud.sub,note:hud.note,power:hud.power||0,actions:(mode.baseActions||[]).map(a=>({...a,id:String(a.id),key:String(a.key||'Space')})),scores:adapter.scores().map(v=>Math.max(0,Math.round(v||0))),meta:{cycle:mode.cycle??0,turn:mode.turn??0,phase:mode.phase||'',lastScorer:mode.lastScorer??-1,throwerIndex:mode.throwerIndex??0,active:mode.active||null,age:mode.age}};send({type:'frame',sequence:++sequence,seat:latest.state.seat,frame});frameAt=now;forceFull=false;}
  }else{codec.interpolate(dt);mode.age+=dt;if(!mode.world.deferAnimation)mode.animate(t);if(lastFrame&&now-lastFrame>2500)ui.note('Waiting for the host connection. The match resumes when they return.');}
  camera();draw();
 };
 mode.receiveLive=event=>{
  if(event.type==='input'&&host){acceptInput(event.slot,event.input);return;}
  if(event.type==='sound'&&!host){ui.sound(event.name);return;}
  if(event.type!=='frame'||host||event.seat!==latest.state.seat)return;const f=event.frame;lastFrame=performance.now();codec.apply(f);ui.power?.(f.power||0);Object.assign(hud,{main:f.main,sub:f.sub,note:f.note});if(f.meta){for(const key of ['turn','phase','lastScorer','throwerIndex','active'])if(f.meta[key]!==undefined)mode[key]=f.meta[key];}mode.baseActions=f.actions;if(mode.rope&&Number.isFinite(f.meta?.cycle)){mode.cycle=f.meta.cycle;const arr=mode.rope.geometry.attributes.position.array;for(let i=0;i<65;i++){const a=i/64*Math.PI;arr[i*3]=-2.5+5*i/64;arr[i*3+1]=1.2-Math.sin(a)*1.16*Math.cos(mode.cycle);arr[i*3+2]=Math.sin(a)*1.16*Math.sin(mode.cycle);}mode.rope.geometry.attributes.position.needsUpdate=true;}latest.state.scores=f.scores;draw();
 };
 mode.receiveRoom=next=>{latest=next;forceFull=true;room.state=next.state;waiting=next.state.ready?.length<room.players.length;if(!host&&next.state.frame)mode.receiveLive({type:'frame',seat:next.state.seat,frame:next.state.frame});if(next.phase==='finished'||next.phase==='cancelled'){
   if(resultShown)return;resultShown=true;finished=true;mode.done=false;const winners=next.state.winners||[],win=winners.includes(slot),tie=!!next.state.draw;mode.score=next.state.scores?.[slot]||0;finish(next.phase==='cancelled'?'ROOM ENDED':win?(tie?'SHARED WIN!':'YOU WIN!'):'ROUND COMPLETE',next.phase==='cancelled'?'A friend left the room. Start another room to play again.':room.players.map((p,i)=>p.name+': '+next.state.scores[i]).join(' · '),win);return;}
  if(next.state.seat!==mode.liveTurn&&mode.liveTurn!==undefined){finished=true;mode.done=true;}mode.liveTurn=next.state.seat;draw();
 };
 const dispose=mode.dispose.bind(mode);mode.dispose=()=>{disposed=true;dispose();};mode.receiveRoom(room);if(room.phase==='playing')send({type:'ready'});return mode;
}
